#!/usr/bin/env python3
"""Convert a CSV file (first row = headers) into a JSON array of objects.

Type inference
--------------
By default each column is assigned one type, inferred from its data.
The inference precedence, from highest to lowest, is:

1. ``null``   -- an empty CSV cell becomes JSON ``null`` (applies per value,
                 regardless of the column type).
2. ``int``    -- every non-empty value in the column parses as an integer.
3. ``float``  -- every non-empty value parses as a float (but not all as int;
                 int is tried first, which is why ``1`` stays an int column).
4. ``boolean``-- every non-empty value is exactly ``true`` or ``false``
                 (case-insensitive).
5. ``string`` -- anything else. A single non-matching row demotes the whole
                 column to string (e.g. a numeric column with one stray word).

With ``--no-infer`` no inference happens at all: every value is emitted as
the original string (only empty cells still become ``null``... actually they
stay empty strings unless you omit this flag -- see below). Under
``--no-infer``, values are kept verbatim as strings.

Usage
-----
    python3 csv2json.py [file.csv]
    python3 csv2json.py --no-infer [file.csv]
    python3 csv2json.py --schema [file.csv]

If no file is given, CSV data is read from stdin. ``--schema`` prints only
the inferred ``{column: type}`` mapping as a JSON object instead of the data.
"""

from __future__ import annotations

import argparse
import csv
import json
import sys


def _is_int(s: str) -> bool:
    try:
        int(s)
        return True
    except ValueError:
        return False


def _is_float(s: str) -> bool:
    try:
        float(s)
        return True
    except ValueError:
        return False


def _is_bool(s: str) -> bool:
    return s.strip().lower() in ("true", "false")


def infer_column_type(values: list[str]) -> str:
    """Infer the type of a column from its raw string values.

    Precedence: int > float > boolean > string (empty cells are ignored for
    inference but become null during conversion; a column whose cells are all
    empty infers as string).
    """
    non_empty = [v for v in values if v != ""]
    if not non_empty:
        return "string"
    if all(_is_int(v) for v in non_empty):
        return "int"
    if all(_is_float(v) for v in non_empty):
        return "float"
    if all(_is_bool(v) for v in non_empty):
        return "boolean"
    return "string"


def convert_value(raw: str, col_type: str):
    """Convert one raw cell according to its column type."""
    if raw == "":
        return None
    if col_type == "int":
        return int(raw)
    if col_type == "float":
        return float(raw)
    if col_type == "boolean":
        return raw.strip().lower() == "true"
    return raw


def load_csv(text: str) -> tuple[list[str], list[list[str]]]:
    reader = csv.reader(text.splitlines())
    rows = [row for row in reader if row]
    if not rows:
        return [], []
    return rows[0], rows[1:]


def convert(text: str, infer_types: bool = True) -> tuple[list[dict], dict]:
    headers, rows = load_csv(text)
    schema = {h: infer_column_type([r[i] for r in rows]) for i, h in enumerate(headers)} if infer_types else {}
    out = []
    for row in rows:
        obj = {}
        for i, h in enumerate(headers):
            raw = row[i] if i < len(row) else ""
            if infer_types:
                obj[h] = convert_value(raw, schema[h])
            else:
                obj[h] = raw
        out.append(obj)
    return out, schema


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Convert CSV to a JSON array of objects.")
    parser.add_argument("file", nargs="?", help="input CSV file (default: stdin)")
    parser.add_argument("--no-infer", action="store_true",
                        help="keep all values as strings")
    parser.add_argument("--schema", action="store_true",
                        help="print only the inferred column-to-type mapping")
    args = parser.parse_args(argv)

    text = open(args.file, encoding="utf-8").read() if args.file else sys.stdin.read()

    if args.no_infer:
        records, _ = convert(text, infer_types=False)
        print(json.dumps(records, indent=2))
        return 0

    records, schema = convert(text, infer_types=True)
    if args.schema:
        print(json.dumps(schema, indent=2))
    else:
        print(json.dumps(records, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

